/* eslint-disable */
// @ts-nocheck — generated by catalog-eject; runtime-correct but TS strict-mode false-positives on inlined catalog body
import { cls } from "@/lib/utils";
import Button from "@/components/ui/Button";
import TextAnimation from "@/components/ui/TextAnimation";
import ImageOrVideo from "@/components/ui/ImageOrVideo";
import ScrollReveal from "@/components/ui/ScrollReveal";

const metrics = [
  {
    value: "100%",
    title: "Professioneller Einsatz",
    description: "Qualifizierte und erfahrene Fachkräfte auf jeder Baustelle.",
    imageSrc: "https://images.pexels.com/photos/35383624/pexels-photo-35383624.jpeg?auto=compress&cs=tinysrgb&h=650&w=940"
  },
  {
    value: "100%",
    title: "Einhaltung von Standards",
    description: "Strikte Einhaltung technischer Vorschriften und Normen.",
    imageSrc: "https://storage.googleapis.com/webild/users/user_3At8P0Z5mHF21VArURutjBjmhus/uploaded-1792060086610-1kvri5u5.jpg"
  }
];

type Metric = {
  value: string;
  title: string;
  description: string;
} & ({ imageSrc: string; videoSrc?: never } | { videoSrc: string; imageSrc?: never });

const MetricsInline = () => (
  <section aria-label="Metrics section" className="py-20">
    <div className="flex flex-col gap-8 md:gap-10">
      <div className="flex flex-col items-center gap-2 w-content-width mx-auto">
        <div className="px-3 py-1 mb-1 text-sm card rounded w-fit">
          <p>{"Warum TatraMont"}</p>
        </div>

        <TextAnimation
          text={"Unsere Professionalität in Zahlen"}
          variant={"slide-up"}
          gradientText={true}
          tag="h2"
          className="md:max-w-8/10 text-6xl 2xl:text-7xl leading-[1.15] font-semibold text-center text-balance"
        />

        <TextAnimation
          text={"Wir konzentrieren uns auf die Qualität und Stabilität, die unsere Geschäftspartner in Deutschland und Österreich von einem professionellen Subunternehmer erwarten."}
          variant={"slide-up"}
          gradientText={false}
          tag="p"
          className="md:max-w-7/10 text-lg md:text-xl leading-snug text-center text-balance"
        />

        {(undefined || undefined) && (
          <div className="flex flex-wrap justify-center gap-3 mt-2 md:mt-3">
            {undefined && <Button text={undefined.text} href={undefined.href} variant="primary"/>}
            {undefined && <Button text={undefined.text} href={undefined.href} variant="secondary"animationDelay={0.1} />}
          </div>
        )}
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-5 w-content-width mx-auto">
        {metrics.map((metric, index) => {
          const isEven = index % 2 === 1;
          const isLast = index === metrics.length - 1;
          const isOddTotal = metrics.length % 2 !== 0;
          const shouldSpanFull = isLast && isOddTotal;

          return (
            <ScrollReveal
              variant="fade"
              key={metric.value}
              className={cls("grid grid-cols-2 gap-5", shouldSpanFull && "md:col-span-2")}
            >
              <div className={cls(
                "flex flex-col justify-between gap-4 xl:gap-5 2xl:gap-6 p-6 xl:p-7 2xl:p-8 card rounded",
                shouldSpanFull ? "aspect-square md:aspect-video" : "aspect-square",
                isEven && "order-2 md:order-1"
              )}>
                <span className="text-5xl md:text-6xl font-semibold leading-snug truncate">{metric.value}</span>
                <div className="flex flex-col gap-2 min-w-0">
                  <span className="text-lg md:text-xl font-semibold">{metric.title}</span>
                  <div className="w-full h-px bg-accent" />
                  <p className="text-xs md:text-sm leading-snug">{metric.description}</p>
                </div>
              </div>

              <div className={cls(
                "rounded overflow-hidden",
                shouldSpanFull ? "aspect-square md:aspect-video" : "aspect-square",
                isEven && "order-1 md:order-2"
              )}>
                <ImageOrVideo imageSrc={metric.imageSrc} videoSrc={metric.videoSrc} />
              </div>
            </ScrollReveal>
          );
        })}
      </div>
    </div>
  </section>
);

export default function MetricsSection() {
  return (
    <div data-webild-section="metrics" data-section="metrics" id="metrics">
      <MetricsInline />
    </div>
  );
}
